/* Module Definition */
void A_IO_L3_in(A_t32 *A, hls::stream<A_t32> &fifo_A_local_out) {
#pragma HLS INLINE OFF
  /* Variable Declaration */
  /* Variable Declaration */

  // array
  // io_L3
  for (ap_uint<6> c3 = 0; c3 <= 31; c3 += 1) {
  #pragma HLS PIPELINE II=1
    // io_L2
    // access_coalesce
    {
      A_t32 in_data;
      A_t32 out_data;
      in_data = A[c3];
      out_data = in_data;
      fifo_A_local_out.write(out_data);
    }
  }
}
