/* Module Definition */
void A_IO_L2_in_intra_trans(int idx, A_t32 local_A[1][1], hls::stream<char> &fifo_A_local_out, bool intra_trans_en) {
#pragma HLS INLINE OFF
  /* Variable Declaration */
  int p0 = idx; // module id
  ap_uint<8> data_split[32];
  #pragma HLS ARRAY_PARTITION variable=data_split complete
  /* Variable Declaration */

  if (!intra_trans_en) return;


  // array
  // io_L3
  // io_L2
  // io_L1
  // pe
  for (ap_uint<6> c5 = 0; c5 <= 31; c5 += 1) {
  #pragma HLS PIPELINE II=1
    // hls_pipeline
    {
      A_t32 in_data;
      A_t1 out_data;
      in_data = local_A[0][c5 / 32];
      for (ap_uint<6> n = 0; n < 32; n++) {
      #pragma HLS UNROLL
        data_split[n] = in_data(7, 0);
        in_data = in_data >> 8;
      }
      int split_idx = (c5) % 32;
      union {unsigned int ui; char ut;} u;
      u.ui = (unsigned int)data_split[split_idx];
      out_data = u.ut;
      fifo_A_local_out.write(out_data);
    }
  }
}
