/* Module Definition */
void A_IO_L2_in_inter_trans(int idx, A_t32 local_A[1][1], hls::stream<A_t32> &fifo_A_in, hls::stream<A_t32> &fifo_A_out, bool inter_trans_en) {
#pragma HLS INLINE OFF
  /* Variable Declaration */
  int p0 = idx; // module id
  /* Variable Declaration */

  if (!inter_trans_en) return;

  for (ap_uint<6> c3 = p0; c3 <= 31; c3 += 1) {
  #pragma HLS PIPELINE II=1
    // io_L2
    if (c3 == p0) {
      // access_coalesce
      {
        A_t32 in_data;
        A_t32 out_data;
        in_data = fifo_A_in.read();
        out_data = in_data;
        local_A[0][0] = out_data;
      }
    } else {
      // access_coalesce
      // hls_pipeline
      {
        A_t32 in_data;
        A_t32 out_data;
        in_data = fifo_A_in.read();
        out_data = in_data;
        fifo_A_out.write(out_data);
      }
    }
  }
}
